//! `docs/plugins/wit-reference.md` is generated from `wit/plugin.wit`. The
//! `///` comments in the WIT are the single definition of what every type,
//! field, case and function of the `plugin` world means; guest bindings
//! generated by `wit-bindgen` contain the same text.
//!
//! The suite fails when a world type, field, case or function has no comment,
//! when the checked-in reference differs from the WIT, and when the import and
//! export tables of `docs/plugins/wasm.md` omit a world function, list one
//! twice, name one the world does not declare, or link a row to the wrong
//! reference anchor. A new world item turns it red until the item is
//! documented, listed and the reference regenerated. It does not check that a
//! comment is true.
//!
//! Regenerate the reference with
//! `ARIA_BLESS_DOCS=1 cargo test -p aria-plugin-wasm --test wit_reference`.

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::PathBuf;

use wit_parser::{
    Docs, Function, PackageId, Resolve, Type, TypeDefKind, TypeId, TypeOwner, WorldId, WorldItem,
};

const WIT: &str = include_str!("../wit/plugin.wit");
const WASM_MD: &str = include_str!("../../../docs/plugins/wasm.md");
const BLESS: &str = "ARIA_BLESS_DOCS";

/// WIT keywords: a name spelled like one is written with a leading `%`.
const KEYWORDS: &[&str] = &[
    "as",
    "async",
    "bool",
    "borrow",
    "char",
    "constructor",
    "enum",
    "error-context",
    "export",
    "f32",
    "f64",
    "flags",
    "func",
    "future",
    "import",
    "include",
    "interface",
    "list",
    "option",
    "own",
    "package",
    "record",
    "resource",
    "result",
    "s16",
    "s32",
    "s64",
    "s8",
    "static",
    "stream",
    "string",
    "tuple",
    "type",
    "u16",
    "u32",
    "u64",
    "u8",
    "use",
    "variant",
    "with",
    "world",
];

struct PluginWorld {
    resolve: Resolve,
    package: PackageId,
    world: WorldId,
}

impl PluginWorld {
    fn load() -> Self {
        let mut resolve = Resolve::new();
        let package = resolve
            .push_source("plugin.wit", WIT)
            .expect("plugin.wit parses");
        let world = resolve
            .select_world(&[package], Some("plugin"))
            .expect("plugin.wit declares the `plugin` world");
        Self {
            resolve,
            package,
            world,
        }
    }

    /// The named types the world declares, in source order.
    fn types(&self) -> Vec<TypeId> {
        let mut types: Vec<TypeId> = self
            .resolve
            .types
            .iter()
            .filter(|(_, def)| def.owner == TypeOwner::World(self.world) && def.name.is_some())
            .map(|(id, _)| id)
            .collect();
        types.sort_by_key(|id| self.resolve.types[*id].span.start());
        types
    }

    /// The world's imported or exported functions, in source order.
    fn functions(&self, exports: bool) -> Vec<&Function> {
        let world = &self.resolve.worlds[self.world];
        let items = if exports {
            &world.exports
        } else {
            &world.imports
        };
        let mut functions: Vec<&Function> = items
            .values()
            .filter_map(|item| match item {
                WorldItem::Function(function) => Some(function),
                WorldItem::Interface { .. } | WorldItem::Type { .. } => None,
            })
            .collect();
        functions.sort_by_key(|function| function.span.start());
        functions
    }

    /// The keyword a type's heading starts with.
    fn keyword(&self, id: TypeId) -> &'static str {
        match &self.resolve.types[id].kind {
            TypeDefKind::Record(_) => "record",
            TypeDefKind::Variant(_) => "variant",
            TypeDefKind::Enum(_) => "enum",
            TypeDefKind::Type(_)
            | TypeDefKind::List(_)
            | TypeDefKind::Option(_)
            | TypeDefKind::Result(_)
            | TypeDefKind::Tuple(_) => "type",
            other => panic!(
                "plugin.wit declares a `{}` type; render it in wit_reference.rs",
                other.as_str()
            ),
        }
    }

    fn type_text(&self, ty: &Type) -> String {
        match ty {
            Type::Bool => "bool".to_owned(),
            Type::U8 => "u8".to_owned(),
            Type::U16 => "u16".to_owned(),
            Type::U32 => "u32".to_owned(),
            Type::U64 => "u64".to_owned(),
            Type::S8 => "s8".to_owned(),
            Type::S16 => "s16".to_owned(),
            Type::S32 => "s32".to_owned(),
            Type::S64 => "s64".to_owned(),
            Type::F32 => "f32".to_owned(),
            Type::F64 => "f64".to_owned(),
            Type::Char => "char".to_owned(),
            Type::String => "string".to_owned(),
            Type::ErrorContext => "error-context".to_owned(),
            Type::Id(id) => match &self.resolve.types[*id].name {
                Some(name) => escaped(name),
                None => self.kind_text(&self.resolve.types[*id].kind),
            },
        }
    }

    /// The WIT spelling of an anonymous type or of the target of an alias.
    fn kind_text(&self, kind: &TypeDefKind) -> String {
        match kind {
            TypeDefKind::Type(inner) => self.type_text(inner),
            TypeDefKind::List(inner) => format!("list<{}>", self.type_text(inner)),
            TypeDefKind::Option(inner) => format!("option<{}>", self.type_text(inner)),
            TypeDefKind::Tuple(tuple) => {
                let types: Vec<String> = tuple.types.iter().map(|ty| self.type_text(ty)).collect();
                format!("tuple<{}>", types.join(", "))
            }
            TypeDefKind::Result(result) => match (&result.ok, &result.err) {
                (None, None) => "result".to_owned(),
                (Some(ok), None) => format!("result<{}>", self.type_text(ok)),
                (None, Some(err)) => format!("result<_, {}>", self.type_text(err)),
                (Some(ok), Some(err)) => {
                    format!("result<{}, {}>", self.type_text(ok), self.type_text(err))
                }
            },
            other => panic!(
                "plugin.wit uses an anonymous `{}` type; render it in wit_reference.rs",
                other.as_str()
            ),
        }
    }

    /// A table cell for `ty`: a link to the type's section when the world
    /// declares it by name, the WIT spelling otherwise.
    fn type_cell(&self, ty: &Type) -> String {
        if let Type::Id(id) = ty {
            let def = &self.resolve.types[*id];
            if let (Some(name), TypeOwner::World(_)) = (&def.name, def.owner) {
                return format!("[`{}`](#{})", escaped(name), slug(&self.type_heading(*id)));
            }
        }
        format!("`{}`", self.type_text(ty))
    }

    fn type_heading(&self, id: TypeId) -> String {
        let name = self.resolve.types[id].name.as_deref().unwrap_or_default();
        format!("{} `{}`", self.keyword(id), escaped(name))
    }

    fn signature(&self, direction: &str, function: &Function) -> String {
        let params: Vec<String> = function
            .params
            .iter()
            .map(|param| format!("{}: {}", escaped(&param.name), self.type_text(&param.ty)))
            .collect();
        let result = function
            .result
            .as_ref()
            .map(|ty| format!(" -> {}", self.type_text(ty)))
            .unwrap_or_default();
        format!(
            "{direction} {}: func({}){result};",
            escaped(&function.name),
            params.join(", ")
        )
    }

    fn render(&self) -> String {
        let world = &self.resolve.worlds[self.world];
        let package = &self.resolve.packages[self.package].name;
        let mut out = String::new();
        let mut headings = BTreeSet::new();
        out.push_str("# WIT reference\n\n");
        out.push_str(
            "<!-- Generated from crates/aria-plugin-wasm/wit/plugin.wit by \
             crates/aria-plugin-wasm/tests/wit_reference.rs. Edit the WIT comments, then run \
             `ARIA_BLESS_DOCS=1 cargo test -p aria-plugin-wasm --test wit_reference`. -->\n\n",
        );
        let _ = writeln!(
            out,
            "Package `{package}`, world `{}`. {}\n",
            world.name,
            cell(&world.docs)
        );
        out.push_str(
            "A component calls the host imports, implements the guest exports, and passes \
             the types below between them. [WebAssembly plugins](wasm.md) lists the \
             permission each import requires and the chapter that covers each function.\n",
        );

        for (title, direction, exports) in [
            ("Host imports", "import", false),
            ("Guest exports", "export", true),
        ] {
            let _ = writeln!(out, "\n## {title}");
            for function in self.functions(exports) {
                let heading = format!("{direction} `{}`", escaped(&function.name));
                assert!(
                    headings.insert(slug(&heading)),
                    "two headings share the anchor `{}`",
                    slug(&heading)
                );
                let _ = writeln!(out, "\n### {heading}\n");
                let _ = writeln!(out, "```wit\n{}\n```", self.signature(direction, function));
                for paragraph in paragraphs(&function.docs) {
                    let _ = writeln!(out, "\n{paragraph}");
                }
            }
        }

        out.push_str("\n## Types\n");
        for id in self.types() {
            let def = &self.resolve.types[id];
            let heading = self.type_heading(id);
            assert!(
                headings.insert(slug(&heading)),
                "two headings share the anchor `{}`",
                slug(&heading)
            );
            let _ = writeln!(out, "\n### {heading}");
            for paragraph in paragraphs(&def.docs) {
                let _ = writeln!(out, "\n{paragraph}");
            }
            match &def.kind {
                TypeDefKind::Record(record) => {
                    out.push_str("\n| Field | Type | Description |\n| --- | --- | --- |\n");
                    for field in &record.fields {
                        let _ = writeln!(
                            out,
                            "| `{}` | {} | {} |",
                            escaped(&field.name),
                            self.type_cell(&field.ty),
                            cell(&field.docs)
                        );
                    }
                }
                TypeDefKind::Variant(variant) => {
                    out.push_str("\n| Case | Payload | Description |\n| --- | --- | --- |\n");
                    for case in &variant.cases {
                        let payload = case
                            .ty
                            .as_ref()
                            .map(|ty| self.type_cell(ty))
                            .unwrap_or_default();
                        let _ = writeln!(
                            out,
                            "| `{}` | {payload} | {} |",
                            escaped(&case.name),
                            cell(&case.docs)
                        );
                    }
                }
                TypeDefKind::Enum(cases) => {
                    out.push_str("\n| Case | Description |\n| --- | --- |\n");
                    for case in &cases.cases {
                        let _ =
                            writeln!(out, "| `{}` | {} |", escaped(&case.name), cell(&case.docs));
                    }
                }
                kind => {
                    let _ = writeln!(out, "\nAlias of `{}`.", self.kind_text(kind));
                }
            }
        }
        out
    }
}

/// `name` as WIT source spells it.
fn escaped(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("%{name}")
    } else {
        name.to_owned()
    }
}

/// The paragraphs of a doc comment, each on one line.
fn paragraphs(docs: &Docs) -> Vec<String> {
    docs.contents
        .as_deref()
        .unwrap_or_default()
        .split("\n\n")
        .map(|paragraph| paragraph.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|paragraph| !paragraph.is_empty())
        .collect()
}

/// A doc comment as one table cell.
fn cell(docs: &Docs) -> String {
    paragraphs(docs).join(" ").replace('|', "\\|")
}

/// The anchor GitHub gives a heading.
fn slug(heading: &str) -> String {
    heading
        .chars()
        .filter_map(|ch| match ch {
            ' ' => Some('-'),
            '-' | '_' => Some(ch),
            ch if ch.is_alphanumeric() => Some(ch.to_ascii_lowercase()),
            _ => None,
        })
        .collect()
}

fn reference_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../docs/plugins/wit-reference.md")
}

#[test]
fn every_world_item_has_documentation() {
    let world = PluginWorld::load();
    let declared = &world.resolve.worlds[world.world];
    let mut missing = Vec::new();
    if paragraphs(&declared.docs).is_empty() {
        missing.push(format!("world {}", declared.name));
    }
    for item in declared.imports.values().chain(declared.exports.values()) {
        if let WorldItem::Interface { id, .. } = item {
            panic!(
                "plugin.wit names the interface {:?}; render interfaces in wit_reference.rs",
                world.resolve.interfaces[*id].name
            );
        }
    }
    for function in world
        .functions(false)
        .into_iter()
        .chain(world.functions(true))
    {
        if paragraphs(&function.docs).is_empty() {
            missing.push(format!("func {}", function.name));
        }
    }
    for id in world.types() {
        let def = &world.resolve.types[id];
        let name = def.name.as_deref().unwrap_or_default();
        if paragraphs(&def.docs).is_empty() {
            missing.push(format!("type {name}"));
        }
        let members: Vec<(&str, &Docs)> = match &def.kind {
            TypeDefKind::Record(record) => record
                .fields
                .iter()
                .map(|field| (field.name.as_str(), &field.docs))
                .collect(),
            TypeDefKind::Variant(variant) => variant
                .cases
                .iter()
                .map(|case| (case.name.as_str(), &case.docs))
                .collect(),
            TypeDefKind::Enum(cases) => cases
                .cases
                .iter()
                .map(|case| (case.name.as_str(), &case.docs))
                .collect(),
            TypeDefKind::Flags(flags) => flags
                .flags
                .iter()
                .map(|flag| (flag.name.as_str(), &flag.docs))
                .collect(),
            _ => Vec::new(),
        };
        for (member, docs) in members {
            if paragraphs(docs).is_empty() {
                missing.push(format!("{name}.{member}"));
            }
        }
    }
    assert!(
        missing.is_empty(),
        "plugin.wit items without a `///` comment:\n{}",
        missing.join("\n")
    );
}

#[test]
fn wit_reference_matches_plugin_wit() {
    let rendered = PluginWorld::load().render();
    let path = reference_path();
    if std::env::var_os(BLESS).is_some() {
        std::fs::write(&path, &rendered)
            .unwrap_or_else(|err| panic!("write {}: {err}", path.display()));
        return;
    }
    let stored = std::fs::read_to_string(&path).unwrap_or_else(|err| {
        panic!(
            "read {}: {err}; run {BLESS}=1 cargo test -p aria-plugin-wasm --test wit_reference",
            path.display()
        )
    });
    if stored != rendered {
        let line = stored
            .lines()
            .zip(rendered.lines())
            .position(|(old, new)| old != new)
            .unwrap_or_else(|| stored.lines().count().min(rendered.lines().count()));
        panic!(
            "{} differs from plugin.wit from line {}: stored {:?}, rendered {:?}. Run \
             {BLESS}=1 cargo test -p aria-plugin-wasm --test wit_reference and review the diff.",
            path.display(),
            line + 1,
            stored.lines().nth(line),
            rendered.lines().nth(line)
        );
    }
}

/// The first cell of every body row of the table under `heading`.
fn table_rows<'a>(markdown: &'a str, heading: &str) -> Vec<&'a str> {
    let mut lines = markdown.lines().skip_while(|line| *line != heading);
    assert!(lines.next().is_some(), "wasm.md has no `{heading}` section");
    lines
        .take_while(|line| !line.starts_with('#'))
        .filter_map(|line| line.strip_prefix("| "))
        .filter_map(|row| row.split(" | ").next())
        .filter(|first| first.contains('`'))
        .collect()
}

#[test]
fn wasm_md_tables_list_every_world_function_once() {
    let world = PluginWorld::load();
    for (heading, direction, exports) in [
        ("### Host Imports", "import", false),
        ("### Guest Exports", "export", true),
    ] {
        let mut listed = BTreeSet::new();
        for first in table_rows(WASM_MD, heading) {
            let name = first
                .split('`')
                .nth(1)
                .unwrap_or_default()
                .trim_start_matches('%');
            assert!(
                listed.insert(name.to_owned()),
                "{heading} lists `{name}` twice"
            );
            let anchor = slug(&format!("{direction} `{}`", escaped(name)));
            assert_eq!(
                first,
                format!("[`{}`](wit-reference.md#{anchor})", escaped(name)),
                "{heading}: the `{name}` row links to its reference section"
            );
        }
        let declared: BTreeSet<String> = world
            .functions(exports)
            .iter()
            .map(|function| function.name.clone())
            .collect();
        let unlisted: Vec<&String> = declared.difference(&listed).collect();
        let unknown: Vec<&String> = listed.difference(&declared).collect();
        assert!(
            unlisted.is_empty() && unknown.is_empty(),
            "{heading}: world functions without a row: {unlisted:?}; rows naming no world \
             function: {unknown:?}"
        );
    }
}
